  [CommSemiring R] [CommSemiring S] {φ : MvPolynomial σ R} {n : ℕ} {f : R →+* S}
  (hf : Function.Injective ⇑f) (h : ((MvPolynomial.map f) φ).IsHomogeneous n) : φ.IsHomogeneous n

